1	import { describe, expect, it } from "vitest";
2	import { compassHeading, createSeaMap, HEADING_COUNT, isNavigable, seaMap, Terrain, terrainAt, type SeaMapSource } from "@pirate-sea-race/content";
3	import {
4	  addShip,
5	  AXIS_SCALE,
6	  canSee,
7	  createMatchState,
8	  defaultSimulationConfig as config,
9	  HEADING_DX,
10	  HEADING_DY,
11	  HEADING_SCALE,
12	  hashState,
13	  hullIsClear,
14	  hullPathIsClear,
15	  INTERACT_BUTTON,
16	  nextRandom,
17	  NOT_DOCKED,
18	  placeShip,
19	  quantizeAxis,
20	  removeShip,
21	  sail,
22	  step,
23	  tileCentre,
24	  toTilePosition,
25	  visibleShipIds,
26	  WORLD_STEP_INTERVAL,
27	  type MatchState,
28	  type PlayerInput,
29	  type ShipState,
30	  type SimulationConfig,
31	} from "./index.js";
32	
33	interface LoggedInput {
34	  readonly frame: number;
35	  readonly shipId: string;
36	  readonly input: PlayerInput;
37	}
38	
39	/** Replays an input log: each entry becomes that ship's held input from its frame on. */
40	function run(initial: MatchState, log: readonly LoggedInput[], steps: number, stepConfig: SimulationConfig = config): MatchState {
41	  let state = initial;
42	  const held: Record<string, PlayerInput> = {};
43	  for (let index = 0; index < steps; index++) {
44	    const frame = state.frame + 1;
45	    for (const entry of log) if (entry.frame === frame) held[entry.shipId] = entry.input;
46	    state = step(stepConfig, state, held);
47	  }
48	  return state;
49	}
50	
51	function matchWithShips(seed: number, ids: readonly string[]): MatchState {
52	  return ids.reduce((state, id) => addShip(config, state, id), createMatchState(seed));
53	}
54	
55	/** `turn` and `throttle` in [-1, 1]; throttle forward is up on the keyboard, a negative moveY. */
56	const helm = (turn: number, throttle: number, buttons = 0): PlayerInput => ({
57	  buttons,
58	  moveX: turn * AXIS_SCALE,
59	  moveY: -throttle * AXIS_SCALE,
60	});
61	const FULL_AHEAD = helm(0, 1);
62	const INTERACT = helm(0, 0, INTERACT_BUTTON);
63	
64	/** Runs one ship through `worldSteps` world steps with a fixed input, returning every intermediate ship. */
65	function sailFor(ship: ShipState, input: PlayerInput, worldSteps: number, sailConfig: SimulationConfig = config): ShipState[] {
66	  const trail: ShipState[] = [];
67	  let current = ship;
68	  for (let index = 0; index < worldSteps; index++) trail.push((current = sail(sailConfig, current, input)));
69	  return trail;
70	}
71	
72	const tile = config.map.subUnitsPerTile;
73	
74	function shipAt(tileX: number, tileY: number, heading: number, sailConfig: SimulationConfig = config): ShipState {
75	  return { id: "a", slot: 0, ...tileCentre(sailConfig, tileX, tileY), heading, speed: 0, dock: NOT_DOCKED };
76	}
77	
78	/** A small test sea: open water with the obstacles drawn in `rows` (`.` sea, `#` land, `%` shoal, `D` dock). */
79	function testConfig(rows: readonly string[], overrides: Partial<SimulationConfig["ship"]> = {}): SimulationConfig {
80	  const source: SeaMapSource = {
81	    name: "test",
82	    widthTiles: rows[0]!.length,
83	    heightTiles: rows.length,
84	    rows,
85	    islands: [{ name: "Test Isle", theme: "tropical", tileX: 0, tileY: 0, widthTiles: rows[0]!.length, heightTiles: rows.length }],
86	    spawnSlots: [{ tileX: 1, tileY: 1, facing: "E" }],
87	  };
88	  const map = createSeaMap(source);
89	  return { ...config, map, spawnSlots: map.spawnSlots, ship: { ...config.ship, ...overrides } };
90	}
91	
92	const inputLog: LoggedInput[] = [
93	  { frame: 1, shipId: "a", input: FULL_AHEAD },
94	  { frame: 10, shipId: "b", input: helm(1, 1) },
95	  { frame: 90, shipId: "a", input: helm(-1, 1) },
96	  { frame: 200, shipId: "c", input: helm(0, -0.6) },
97	  { frame: 320, shipId: "b", input: helm(0, 0) },
98	  { frame: 450, shipId: "a", input: helm(0, -1, INTERACT_BUTTON) },
99	];
100	
101	describe("determinism", () => {
102	  it("gives the same hash for the same initial state and input log after 600 steps", () => {
103	    const first = run(matchWithShips(1234, ["a", "b", "c"]), inputLog, 600);
104	    const second = run(matchWithShips(1234, ["a", "b", "c"]), inputLog, 600);
105	    expect(first.frame).toBe(600);
106	    expect(hashState(first)).toBe(hashState(second));
107	    expect(first).toEqual(second);
108	  });
109	
110	  it("gives a different hash when one input changes", () => {
111	    const changed = inputLog.map((entry, index) => (index === 1 ? { ...entry, input: helm(-1, 1) } : entry));
112	    const original = run(matchWithShips(1234, ["a", "b", "c"]), inputLog, 600);
113	    const altered = run(matchWithShips(1234, ["a", "b", "c"]), changed, 600);
114	    expect(hashState(altered)).not.toBe(hashState(original));
115	  });
116	
117	  it("hashes the complete state, including the generator and the dock", () => {
118	    const state = matchWithShips(1, ["a"]);
119	    expect(hashState({ ...state, rng: state.rng + 1 })).not.toBe(hashState(state));
120	    expect(hashState({ ...state, frame: 1 })).not.toBe(hashState(state));
121	    const docked = { ...state, ships: state.ships.map((ship) => ({ ...ship, dock: 0 })) };
122	    expect(hashState(docked)).not.toBe(hashState(state));
123	  });
124	
125	  it("does not depend on key order", () => {
126	    const state = matchWithShips(99, ["a", "b"]);
127	    const reordered = {
128	      ships: state.ships.map((ship) => {
129	        const { dock, speed, heading, y, x, slot, id } = ship;
130	        return { dock, speed, heading, y, x, slot, id };
131	      }),
132	      rng: state.rng,
133	      worldTick: state.worldTick,
134	      frame: state.frame,
135	    };
136	    expect(hashState(reordered)).toBe(hashState(state));
137	  });
138	
139	  it("keeps every number in the state an integer", () => {
140	    const state = run(matchWithShips(7, ["a", "b", "c"]), inputLog, 600);
141	    for (const ship of state.ships) {
142	      for (const value of [ship.x, ship.y, ship.heading, ship.speed, ship.dock, ship.slot]) expect(Number.isInteger(value)).toBe(true);
143	    }
144	    expect(state.ships.some((ship) => ship.speed !== 0)).toBe(true);
145	  });
146	
147	  it("does not mutate the state it is given", () => {
148	    const state = Object.freeze(matchWithShips(5, ["a"]));
149	    expect(() => step(config, state, { a: FULL_AHEAD })).not.toThrow();
150	    expect(state.frame).toBe(0);
151	  });
152	});
153	
154	describe("clock", () => {
155	  it("advances world logic only on every third step", () => {
156	    let state = matchWithShips(42, ["a"]);
157	    const inputs = { a: FULL_AHEAD };
158	    for (let frame = 1; frame <= 30; frame++) {
159	      const before = state;
160	      state = step(config, state, inputs);
161	      expect(state.frame).toBe(frame);
162	      if (frame % WORLD_STEP_INTERVAL === 0) {
163	        expect(state.worldTick).toBe(before.worldTick + 1);
164	        expect(state.ships[0]!.speed).toBe(before.ships[0]!.speed + config.ship.acceleration);
165	      } else {
166	        expect(state.worldTick).toBe(before.worldTick);
167	        expect(state.ships).toBe(before.ships);
168	      }
169	    }
170	    expect(state.worldTick).toBe(10);
171	  });
172	});
