174	describe("heading table", () => {
175	  it("has HEADING_COUNT unit vectors, east first, turning clockwise with y down", () => {
176	    expect(HEADING_DX).toHaveLength(HEADING_COUNT);
177	    expect([HEADING_DX[0], HEADING_DY[0]]).toEqual([HEADING_SCALE, 0]);
178	    expect([HEADING_DX[16], HEADING_DY[16]]).toEqual([0, HEADING_SCALE]);
179	    expect([HEADING_DX[32], HEADING_DY[32]]).toEqual([-HEADING_SCALE, 0]);
180	    expect([HEADING_DX[48], HEADING_DY[48]]).toEqual([0, -HEADING_SCALE]);
181	    expect(HEADING_DX[8]).toBe(HEADING_DY[8]);
182	    for (let heading = 0; heading < HEADING_COUNT; heading++) {
183	      const dx = HEADING_DX[heading]!;
184	      const dy = HEADING_DY[heading]!;
185	      expect(Number.isInteger(dx) && Number.isInteger(dy)).toBe(true);
186	      // Each entry is a rounded unit vector: its length is within a unit of HEADING_SCALE.
187	      expect(Math.abs(dx * dx + dy * dy - HEADING_SCALE * HEADING_SCALE)).toBeLessThanOrEqual(2 * HEADING_SCALE);
188	      // Mirror symmetry about the x axis.
189	      expect(HEADING_DX[(HEADING_COUNT - heading) % HEADING_COUNT]).toBe(dx);
190	      expect(HEADING_DY[(HEADING_COUNT - heading) % HEADING_COUNT]).toBe(dy === 0 ? 0 : -dy);
191	    }
192	  });
193	
194	  it("matches the compass directions spawn slots are authored with", () => {
195	    expect(compassHeading("E")).toBe(0);
196	    expect(compassHeading("S")).toBe(16);
197	    expect(compassHeading("NW")).toBe(40);
198	  });
199	});
