201	describe("sailing", () => {
202	  const open = testConfig(Array.from({ length: 40 }, () => ".".repeat(200)));
203	  const start = shipAt(20, 20, 0, open);
204	
205	  it("accelerates under throttle to the maximum speed and holds it", () => {
206	    const trail = sailFor(start, FULL_AHEAD, 40, open);
207	    expect(trail[0]!.speed).toBe(config.ship.acceleration);
208	    expect(trail[1]!.speed).toBe(2 * config.ship.acceleration);
209	    const stepsToFull = config.ship.maxSpeed / config.ship.acceleration;
