217	
218	  it("brakes faster than it coasts, then reverses slowly from a stop", () => {
219	    const underWay = sailFor(start, FULL_AHEAD, 30, open).at(-1)!;
220	    const braking = sailFor(underWay, helm(0, -1), 40, open);
221	    const coasting = sailFor(underWay, helm(0, 0), 40, open);
222	    const stopAt = (trail: ShipState[]) => trail.findIndex((ship) => ship.speed === 0);
223	    expect(braking[0]!.speed).toBe(config.ship.maxSpeed - config.ship.braking);
