233	
234	  it("turns the integer heading at the turn rate, both ways, wrapping around", () => {
235	    const starboard = sailFor(start, helm(1, 0), HEADING_COUNT + 3, open);
236	    expect(starboard.slice(0, 3).map((ship) => ship.heading)).toEqual([1, 2, 3].map((turns) => turns * config.ship.turnRate));
237	    expect(starboard[HEADING_COUNT / config.ship.turnRate - 1]!.heading).toBe(0);
238	    const port = sailFor(start, helm(-1, 0), 2, open);
