262	    const wild = step(config, step(config, step(config, matchWithShips(3, ["a"]), {}), {}), { a: { buttons: 0, moveX: 0, moveY: -50 * AXIS_SCALE } });
263	    expect(wild.ships[0]!.speed).toBe(config.ship.acceleration);
