138	  if (landTiles === 0) issues.push("no land");
139	  if (shoalTiles === 0) issues.push("no shoals");
140	
141	  const neighbours = (tileX: number, tileY: number) => [
142	    [tileX + 1, tileY],
143	    [tileX - 1, tileY],
144	    [tileX, tileY + 1],
145	    [tileX, tileY - 1],
146	  ] as const;
