2	 * The last step of `npm run build`: proves the build output runs, not just that it compiled. It loads every workspace
3	 * package through its `default` export (the built `dist/`), starts the built server (`node apps/server/dist/main.js`)
4	 * on a free port, waits for its health check, creates a private match through the Colyseus SDK and waits for the
5	 * creator's ship, and checks that the production entry offers no test-only placement route. Every wait is bounded and
6	 * the server is killed on every path, so a failure fails the build with its real error and no process outlives the
7	 * script.
8	 */
9	import { spawn, type ChildProcess } from "node:child_process";
10	import { createInterface } from "node:readline";
11	import { fileURLToPath } from "node:url";
12	
13	const root = fileURLToPath(new URL("..", import.meta.url));
14	const SERVER_ENTRY = "apps/server/dist/main.js";
15	const LISTENING_LINE = /listening on ws:\/\/localhost:(\d+)/;
16	
17	const LISTEN_TIMEOUT_MS = 20_000;
18	const HEALTH_TIMEOUT_MS = 10_000;
19	const MATCH_TIMEOUT_MS = 15_000;
20	const STOP_TIMEOUT_MS = 5_000;
21	/** Everything together stays far below the build check's 600 s. */
22	const OVERALL_TIMEOUT_MS = 90_000;
23	
24	/** The built entry points, as a consumer without the `@pirate-sea-race/source` condition resolves them. */
25	const WORKSPACE_EXPORTS = [
26	  "@pirate-sea-race/content",
27	  "@pirate-sea-race/protocol",
28	  "@pirate-sea-race/simulation",
29	  "@pirate-sea-race/server",
30	  "@pirate-sea-race/server/schema",
31	  "@pirate-sea-race/test-tools",
32	];
33	
34	let server: ChildProcess | undefined;
35	
36	function log(message: string): void {
37	  console.log(`build smoke: ${message}`);
38	}
39	
40	function withTimeout<T>(promise: Promise<T>, timeoutMs: number, what: string): Promise<T> {
41	  let timer: NodeJS.Timeout | undefined;
42	  const timeout = new Promise<never>((_, reject) => {
43	    timer = setTimeout(() => reject(new Error(`${what} did not finish within ${timeoutMs} ms`)), timeoutMs);
44	  });
45	  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
46	}
47	
48	function sleep(ms: number): Promise<void> {
49	  return new Promise((resolve) => setTimeout(resolve, ms));
50	}
51	
52	function running(child: ChildProcess): boolean {
53	  return child.exitCode === null && child.signalCode === null;
54	}
55	
56	async function checkWorkspaceExports(): Promise<void> {
57	  for (const specifier of WORKSPACE_EXPORTS) {
58	    const resolved = fileURLToPath(import.meta.resolve(specifier));
59	    if (!/[\\/]dist[\\/][^\\/]+\.js$/.test(resolved)) throw new Error(`${specifier} resolves to ${resolved}, not to its dist/`);
60	    const module = (await import(specifier)) as Record<string, unknown>;
61	    if (Object.keys(module).length === 0) throw new Error(`${specifier} (${resolved}) exports nothing`);
62	  }
63	  log(`${WORKSPACE_EXPORTS.length} workspace exports load from dist/`);
64	}
65	
66	/** Starts the built server on a free port and resolves with the port from its "listening" line. */
67	function startServer(): Promise<number> {
68	  const child = spawn(process.execPath, [SERVER_ENTRY], {
69	    cwd: root,
70	    env: { ...process.env, PORT: "0", PIRATE_SEA_RACE_TEST_PLACEMENT: "1" },
71	    stdio: ["ignore", "pipe", "pipe"],
72	  });
73	  server = child;
74	  child.stderr!.on("data", (chunk: Buffer) => process.stderr.write(chunk));
75	  return withTimeout(
76	    new Promise<number>((resolve, reject) => {
77	      createInterface({ input: child.stdout! }).on("line", (line) => {
78	        console.log(`  server: ${line}`);
79	        const match = LISTENING_LINE.exec(line);
80	        if (match !== null) resolve(Number(match[1]));
81	      });
82	      child.once("error", reject);
83	      child.once("exit", (code, signal) => reject(new Error(`${SERVER_ENTRY} exited (code ${code}, signal ${signal}) before listening`)));
84	    }),
85	    LISTEN_TIMEOUT_MS,
86	    `${SERVER_ENTRY} listening`,
87	  );
88	}
89	
90	async function waitForHealth(endpoint: string): Promise<void> {
91	  const deadline = Date.now() + HEALTH_TIMEOUT_MS;
92	  let last: unknown;
93	  while (Date.now() < deadline) {
94	    try {
95	      const response = await fetch(`${endpoint}/__healthcheck`, { signal: AbortSignal.timeout(1000) });
96	      if (response.ok) return;
97	      last = new Error(`HTTP ${response.status}`);
98	    } catch (error) {
99	      last = error;
100	    }
101	    await sleep(100);
102	  }
103	  throw new Error(`${endpoint}/__healthcheck did not answer OK within ${HEALTH_TIMEOUT_MS} ms`, { cause: last });
104	}
105	
106	async function createMatch(endpoint: string): Promise<void> {
107	  const { HeadlessClient } = await import("@pirate-sea-race/test-tools");
108	  const { TEST_PLACEMENT_PATH } = await import("@pirate-sea-race/protocol");
109	  const host = await withTimeout(HeadlessClient.create(endpoint), MATCH_TIMEOUT_MS, "creating a match");
110	  try {
111	    const ship = host.ship();
112	    if (!/^[A-Z0-9]{6}$/.test(host.code)) throw new Error(`the match has no code (got "${host.code}")`);
113	    if (ship === undefined || host.playerCount !== 1) throw new Error("the creator's ship is not in the match state");
114	    log(`created match ${host.code}; the creator's ship is at (${ship.x}, ${ship.y})`);
115	    // The production entry never reads the test-placement setting, even when the environment sets it.
116	    const response = await fetch(`${endpoint}${TEST_PLACEMENT_PATH}`, {
117	      method: "POST",
118	      headers: { "content-type": "application/json" },
119	      body: JSON.stringify({ code: host.code, sessionId: host.sessionId, tileX: 100, tileY: 76, heading: 0 }),
120	      signal: AbortSignal.timeout(HEALTH_TIMEOUT_MS),
121	    });
122	    if (response.status !== 404) throw new Error(`the production server answered the test placement route with HTTP ${response.status}`);
123	    log("the production server offers no test placement");
124	  } finally {
125	    await withTimeout(host.leave(), STOP_TIMEOUT_MS, "leaving the match").catch(() => undefined);
126	  }
127	}
128	
129	/** Stops the server: SIGTERM lets it drain; SIGKILL follows if it does not exit in time. */
130	async function stopServer(): Promise<void> {
131	  const child = server;
132	  if (child === undefined || !running(child)) return;
133	  const exited = new Promise<void>((resolve) => child.once("exit", () => resolve()));
134	  child.kill("SIGTERM");
135	  await withTimeout(exited, STOP_TIMEOUT_MS, "server shutdown").catch(async () => {
136	    child.kill("SIGKILL");
137	    await withTimeout(exited, STOP_TIMEOUT_MS, "killing the server");
138	  });
139	}
140	
141	// Last resort for paths that skip `finally`: an exit, or a signal from whoever runs the build.
142	process.once("exit", () => {
143	  if (server !== undefined && running(server)) server.kill("SIGKILL");
144	});
145	for (const signal of ["SIGINT", "SIGTERM"] as const) {
146	  process.once(signal, () => {
147	    console.error(`build smoke: interrupted by ${signal}`);
148	    process.exit(1);
149	  });
150	}
151	
152	async function main(): Promise<void> {
153	  await checkWorkspaceExports();
154	  const port = await startServer();
155	  const endpoint = `http://localhost:${port}`;
156	  log(`${SERVER_ENTRY} listens on port ${port}`);
157	  await waitForHealth(endpoint);
158	  log("health check answers");
159	  await createMatch(endpoint);
160	}
161	
162	let failed = false;
163	try {
164	  await withTimeout(main(), OVERALL_TIMEOUT_MS, "the build smoke test");
165	  log("passed");
166	} catch (error) {
167	  failed = true;
168	  console.error("build smoke: FAILED");
169	  console.error(error);
170	} finally {
171	  await stopServer().catch((error: unknown) => {
172	    failed = true;
173	    console.error("build smoke: could not stop the server", error);
174	  });
175	}
176	process.exit(failed ? 1 : 0);
